import json,hashlib,time,os,shutil
from pathlib import Path
root=Path.home()/'rca-t048/work';matrix=json.loads((root/'results/T-048/ma-tran.json').read_text());started=time.monotonic()
def sha(p):
 with p.open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
for rel,digest in matrix['source_sha256'].items():assert sha(root/rel)==digest,rel
active=[]
for p in Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:cmd=(p/'cmdline').read_bytes()
 except (OSError,PermissionError):continue
 if b'results/T-048/scripts/chay.py' in cmd and b'python' in cmd.split(b'\0')[0]:active.append(p.name)
assert not active,active
files=[];leaf_count=0
for name in ('r0-ec2-001','t4-ec2-001','t4b-ec2-001'):
 parent=root/'results/T-048/runs'/name;status=json.loads((parent/'kiem.json').read_text());assert status['success'] and len(status['finished'])==status['jobs']
 for child in status['finished']:
  leaf=root/'results/T-048/runs'/child;meta=json.loads((leaf/'kiem.json').read_text())
  assert sha(leaf/'ban-ghi.jsonl')==meta['phase1_sha256'] and sha(leaf/'trung-gian.jsonl')==meta['intermediate_sha256'];leaf_count+=1
  for p in leaf.iterdir():
   if p.is_file():files.append(dict(path=p.relative_to(root).as_posix(),bytes=p.stat().st_size,sha256=sha(p)))
 for p in parent.iterdir():
  if p.is_file():files.append(dict(path=p.relative_to(root).as_posix(),bytes=p.stat().st_size,sha256=sha(p)))
result=dict(closed=True,method_sources_match=True,active_M1=active,leaf_count=leaf_count,files=files,total_bytes=sum(e['bytes'] for e in files),disk_free=shutil.disk_usage(root).free,wall_seconds=time.monotonic()-started)
print(json.dumps(result))
